DECLARE @category varchar(24)=?,@value varchar(10)=?,@name nvarchar(24)=?,@ordering int=?,@active bit=?,@from date=?,@to date=?,@remarks nvarchar(240)=?,@actor nvarchar(128)=?,@now datetimeoffset(7)=?; DECLARE @saved TABLE(version bigint); INSERT INTO dbo.m_code(category_id,code_value,code_name,display_order,is_active,valid_from,valid_to,remarks,is_protected,created_at,created_by,updated_at,updated_by,row_version) OUTPUT INSERTED.row_version INTO @saved VALUES (@category,@value,@name,@ordering,@active,@from,@to,@remarks,0,@now,@actor,@now,@actor,1); SELECT version FROM @saved;
